function(type, msg) {
        const xhr_response = vowOS.service.syncExecute('hiutils', {
            api: type,
            args: msg
        })
        return xhr_response
    }

serviceSyncExecute.source:
function (service, args) {
            if (!args?.api) {
                console.error('wrong parameter, should set api')
                return false
            }

            if (this.httpRequest == null) {
                this.httpRequest = new XMLHttpRequest()
            }

            if (!this.portValidated) {
                const options = [
                    'https://localhost:9888/service/',
                    'http://localhost:9009/service/'
                ]

                for (const option of options) {
                    const url = option + service
                    const result = this.executeHttpRequest(url, args)

                    if (result.success) {
                        this.httpOption = option
                        this.portValidated = true
                        console.log(`request ok: ${option}`)
                        return result.data
                    }
                }

                this.portValidated = true
                console.warn('all attempt are invalid, use default https.')
                return false
            }

            const finalUrl = this.httpOption + service
            const finalResult = this.executeHttpRequest(finalUrl, args)

            return finalResult.success ? finalResult.data : false
        }

serviceGetIdentifier.source:
function() {
            if(window.navigator.appIdentifier !== 'undefined' && window.vowOSContext && typeof(window.vowOSContext?.getAppIdentifier) === 'function') {
                return window.vowOSContext.getAppIdentifier()
            }

            return ''
        }

serviceExecuteHttpRequest.source:
function (url, args) {
            try {
                console.log('post request to ' + url)
                this.httpRequest.open('POST', url, false)
                this.httpRequest.setRequestHeader('identifier', this.getIdentifier())
                this.httpRequest.send(JSON.stringify(args))

                if (this.httpRequest.status == 200) {
                    this.httpServeLostErrNum = 0
                    return {
                        success: true,
                        data: this.processResponse(this.httpRequest)
                    }
                } else {
                    console.error('http request failed:' + this.httpRequest.status)
                    return { success: false }
                }
            } catch (e) {
                console.error(`error occurred(${e.message})`)
                if(this.httpRequest.status === 0) this.httpServeLostErrNum++
                if (this.wssServeLostErrNum >= 2 && this.httpServeLostErrNum >= 2) {
                    if (this.launchTimer !== null) clearTimeout(this.launchTimer)
                    console.error(`Server lost (WS err:${this.wssServeLostErrNum}, HTTP err:${this.httpServeLostErrNum}). Relaunching in 5s...`);
                    this.launchTimer = setTimeout(() => {
                        this.reLaunchService()
                        this.launchTimer = null
                    }, 5000)
                    this.wssServeLostErrNum = 0
                    this.httpServeLostErrNum = 0
                }
                return { success: false }
            }
        }
